   { "label": "Wikipedia — Hakim Mosque, Isfahan", "url": "https://en.wikipedia.org/wiki/Hakim_Mosque,_Isfahan" },
   { "label": "EavarTravel — Isfahan Hakim Mosque", "url": "https://www.eavartravel.com/blog/2024/8/18/160968/isfahan-hakim-mosque/" }
